    h, w = len(grid), len(grid[0])
    vals = [row[0] for row in grid]
    observed = [(i, v) for i, v in enumerate(vals) if v != 0]
    if not observed:
        return [row[:] for row in grid]
    period = next((p for p in range(1, h + 1)
                   if all(va == vb for a, va in observed for b, vb in observed
                          if a < b and (a-b) % p == 0)), h)
    phases = {i % period: v for i, v in observed}
    known = sorted(phases)
    for k in range(period):
        if k not in phases:
            phases[k] = phases[min(known, key=lambda j: (k-j) % period)]
    return [[phases[i % period]] * w for i in range(h)]
